const updateIntent = `-- name: UpdateIntent :execrows
UPDATE payment.payment_intents SET
    payment_method_token_ref = $1,
    intent_status = $2,
    status_reason_code = $3,
    aggregate_version = $4,
    active_operation_id = $5,
    latest_operation_id = $6,
    authorized_minor = $7,
    captured_minor = $8,
    reserved_capture_minor = $9,
    policy_version = $10,
    cancel_requested_at_utc = $11,
    expiry_flagged_at_utc = $12,
    frozen_at_utc = $13,
    action_ref = $14,
    action_expires_at_utc = $15,
    updated_at_utc = $16
WHERE intent_id = $17 AND aggregate_version = $18
`

type UpdateIntentParams struct {
	PaymentMethodTokenRef *string
	IntentStatus          string
	StatusReasonCode      *string
	NewVersion            int64
	ActiveOperationID     *string
	LatestOperationID     *string
	AuthorizedMinor       int64
	CapturedMinor         int64
	ReservedCaptureMinor  int64
	PolicyVersion         string
	CancelRequestedAtUtc  *time.Time
	ExpiryFlaggedAtUtc    *time.Time
	FrozenAtUtc           *time.Time
	ActionRef             *string
	ActionExpiresAtUtc    *time.Time
	UpdatedAtUtc          time.Time
	IntentID              string
	ExpectedVersion       int64
}

// Compare-and-swap on aggregate_version (06-01 PI-INV-08).
func (q *Queries) UpdateIntent(ctx context.Context, arg UpdateIntentParams) (int64, error) {
	result, err := q.db.Exec(ctx, updateIntent,
		arg.PaymentMethodTokenRef,
		arg.IntentStatus,
		arg.StatusReasonCode,
		arg.NewVersion,
		arg.ActiveOperationID,
		arg.LatestOperationID,
		arg.AuthorizedMinor,
		arg.CapturedMinor,
		arg.ReservedCaptureMinor,
		arg.PolicyVersion,
		arg.CancelRequestedAtUtc,
		arg.ExpiryFlaggedAtUtc,
		arg.FrozenAtUtc,
		arg.ActionRef,
		arg.ActionExpiresAtUtc,
		arg.UpdatedAtUtc,
		arg.IntentID,
		arg.ExpectedVersion,
	)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

